/** EAN-13 with the restricted in-store "200" prefix: never a real retail GTIN. */
export function barcodeFor(index) {
  const base = `200${String(100000 + index).padStart(9, "0")}`;
  let sum = 0;
  for (let i = 0; i < 12; i += 1)
    sum += Number(base[i]) * (i % 2 === 0 ? 1 : 3);
  return `${base}${(10 - (sum % 10)) % 10}`;
}

// Per-branch stocking: quantity factor, and categories that are NOT stocked
